//! Replay requests generated by the pinned Grafana Prometheus backend plugin.

#[cfg(test)]
use assert2::assert;
use serde_json::{Value, json};

use super::{client_replay_proxy::RecordingProxy, upstream_http::TestResult};

const RATE_INFO: &str = "PromQL info: metric might not be a counter, __type__ label is not set to \"counter\" or \"histogram\", got \"\": \"http_requests_total\" (1:6)";

fn expected_infos(case: &ReplayCase) -> Value {
    if case.id.ends_with("rate") {
        json!([RATE_INFO])
    } else {
        json!([])
    }
}

struct ReplayCase {
    id: &'static str,
    expression: &'static str,
    range: bool,
    start_ms: i64,
    values: &'static [f64],
    labels: fn() -> Value,
}

fn selector_labels() -> Value {
    json!({"__name__":"http_requests_total","job":"api","method":"GET","code":"200"})
}

fn rate_labels() -> Value {
    json!({"job":"api","method":"GET","code":"200"})
}

fn sum_labels() -> Value {
    json!({})
}

const CASES: &[ReplayCase] = &[
    ReplayCase {
        id: "instant-selector",
        expression: r#"http_requests_total{method="GET"}"#,
        range: false,
        start_ms: 45000,
        values: &[120.0],
        labels: selector_labels,
    },
    ReplayCase {
        id: "instant-sum",
        expression: "sum(http_requests_total)",
        range: false,
        start_ms: 45000,
        values: &[128.0],
        labels: sum_labels,
    },
    ReplayCase {
        id: "instant-rate",
        expression: r#"rate(http_requests_total{method="GET"}[30s])"#,
        range: false,
        start_ms: 45000,
        values: &[3.0],
        labels: rate_labels,
    },
    ReplayCase {
        id: "range-selector",
        expression: r#"http_requests_total{method="GET"}"#,
        range: true,
        start_ms: 0,
        values: &[0.0, 30.0, 75.0, 120.0],
        labels: selector_labels,
    },
    ReplayCase {
        id: "range-sum",
        expression: "sum(http_requests_total)",
        range: true,
        start_ms: 0,
        values: &[0.0, 33.0, 80.0, 128.0],
        labels: sum_labels,
    },
    // At t=30, zero extrapolation caps the left padding at ten seconds:
    // (75-30) * (25/15) / 30 = 2.5. At t=45 the full window yields 3.
    ReplayCase {
        id: "range-rate",
        expression: r#"rate(http_requests_total{method="GET"}[30s])"#,
        range: true,
        start_ms: 30000,
        values: &[2.5, 3.0],
        labels: rate_labels,
    },
];

fn dashboard_request(case: &ReplayCase, uid: &str) -> Value {
    json!({"from":case.start_ms.to_string(),"to":"45000","queries":[{
        "refId":"A","datasource":{"type":"prometheus","uid":uid},"expr":case.expression,
        "instant":!case.range,"range":case.range,"queryType":if case.range {"range"} else {"instant"},
        "intervalMs":15000,"maxDataPoints":1000}]})
}

fn ledger(case: &ReplayCase) -> Value {
    json!({"labels":(case.labels)(),"infos":expected_infos(case),"samples":case.values.iter().enumerate().map(|(index,value)|
        json!([case.start_ms + i64::try_from(index).expect("bounded fixture") * 15000,value])).collect::<Vec<_>>()})
}

fn canonical_response(case: &ReplayCase, response: &Value) -> TestResult<Value> {
    let expected_type = if case.range { "matrix" } else { "vector" };
    let result = response["data"]["result"]
        .as_array()
        .ok_or("Prometheus result missing")?;
    if response["status"] != "success"
        || response["data"]["resultType"] != expected_type
        || result.len() != 1
        || response
            .get("warnings")
            .cloned()
            .unwrap_or_else(|| json!([]))
            != json!([])
        || response.get("infos").cloned().unwrap_or_else(|| json!([])) != expected_infos(case)
    {
        return Err(
            format!("unexpected Prometheus result shape or annotations: {response}").into(),
        );
    }
    let samples = if case.range {
        result[0]["values"]
            .as_array()
            .ok_or("matrix values missing")?
            .clone()
    } else {
        vec![result[0]["value"].clone()]
    };
    let mut points = Vec::new();
    for sample in samples {
        let timestamp = sample[0].as_f64().ok_or("sample timestamp missing")? * 1000.0;
        let value = sample[1]
            .as_str()
            .ok_or("sample value missing")?
            .parse::<f64>()?;
        if !timestamp.is_finite() || !value.is_finite() {
            return Err("non-finite replay sample".into());
        }
        points.push(json!([timestamp, value]));
    }
    Ok(json!({"labels":result[0]["metric"],"samples":points}))
}

fn matches_ledger(expected: &Value, actual: &Value) -> bool {
    if expected["labels"] != actual["labels"] {
        return false;
    }
    let Some(expected) = expected["samples"].as_array() else {
        return false;
    };
    let Some(actual) = actual["samples"].as_array() else {
        return false;
    };
    expected.len() == actual.len()
        && expected.iter().zip(actual).all(|(expected, actual)| {
            expected.as_array().is_some_and(|point| point.len() == 2)
                && actual.as_array().is_some_and(|point| point.len() == 2)
                && (0..2).all(|index| {
                    expected[index]
                        .as_f64()
                        .is_some_and(|value| actual[index].as_f64() == Some(value))
                })
        })
}

fn canonical_frames(response: &Value, expected: &Value) -> TestResult<Value> {
    let result = &response["body"]["results"]["A"];
    if response["status"] != 200 || result.get("error").is_some() {
        return Err("Grafana query failed".into());
    }
    let frames = result["frames"]
        .as_array()
        .ok_or("Grafana frames missing")?;
    if frames.len() != 1 {
        return Err("Grafana replay requires exactly one series frame".into());
    }
    let frame = &frames[0];
    let fields = frame["schema"]["fields"]
        .as_array()
        .ok_or("frame fields missing")?;
    let columns = frame["data"]["values"]
        .as_array()
        .ok_or("frame columns missing")?;
    if fields.len() != 2 || columns.len() != 2 {
        return Err("unexpected Prometheus frame columns".into());
    }
    let time_index = fields
        .iter()
        .position(|field| field["type"] == "time")
        .ok_or("time field missing")?;
    let value_index = fields
        .iter()
        .position(|field| field["type"] == "number")
        .ok_or("value field missing")?;
    let times = columns[time_index]
        .as_array()
        .ok_or("time values missing")?;
    let values = columns[value_index]
        .as_array()
        .ok_or("numeric values missing")?;
    if times.len() != values.len() {
        return Err("frame time/value lengths differ".into());
    }
    let actual = json!({"labels":fields[value_index].get("labels").cloned().unwrap_or_else(||json!({})),
        "samples":times.iter().zip(values).map(|(time,value)|json!([time,value])).collect::<Vec<_>>()});
    if !matches_ledger(expected, &actual) {
        return Err(format!("Grafana frame differs from independent ledger: {actual}").into());
    }
    let mut meta = frame["schema"]
        .get("meta")
        .cloned()
        .unwrap_or_else(|| json!({}));
    if let Some(meta) = meta.as_object_mut() {
        meta.remove("stats");
        meta.remove("executedQueryString");
    }
    let notices = expected["infos"]
        .as_array()
        .ok_or("annotation ledger missing")?
        .iter()
        .map(|message| json!({"severity":"info","text":message}))
        .collect::<Vec<_>>();
    if meta.get("notices").cloned().unwrap_or_else(|| json!([])) != json!(notices) {
        return Err("Grafana notices differ from annotation ledger".into());
    }
    Ok(json!({"fields":fields,"data":frame["data"],"meta":meta}))
}

async fn replay(client: &reqwest::Client, base: &str, request: &Value) -> TestResult<Value> {
    if request["tenant"] != "grafana" {
        return Err("recorded tenant differs".into());
    }
    let method = request["method"]
        .as_str()
        .ok_or("method missing")?
        .parse::<reqwest::Method>()?;
    let uri = request["uri"].as_str().ok_or("URI missing")?;
    let mut outgoing = client
        .request(method, format!("{base}{uri}"))
        .header("X-Scope-OrgID", "grafana")
        .body(
            request["body"]
                .as_str()
                .ok_or("request body missing")?
                .to_string(),
        );
    if let Some(content_type) = request["content_type"]
        .as_str()
        .filter(|value| !value.is_empty())
    {
        outgoing = outgoing.header("Content-Type", content_type);
    }
    Ok(outgoing.send().await?.error_for_status()?.json().await?)
}

pub struct ReplayBackend<'a> {
    pub base: &'a str,
    pub proxy: &'a RecordingProxy,
    pub uid: &'a str,
}

/// Compare both plugin requests and backend answers with the input ledger.
///
/// # Errors
/// Returns an error for transport failures, invalid responses or any mismatch.
pub async fn run(
    client: &reqwest::Client,
    grafana: &str,
    oracle: ReplayBackend<'_>,
    candidate: ReplayBackend<'_>,
) -> TestResult {
    let mut report = json!({"suite":"grafana-prometheus-client-replay","status":"running","planned":CASES.len(),
        "grafana_image_tag":std::env::var("KRABKA_GRAFANA_IMAGE_TAG").ok(),
        "prometheus_image_tag":std::env::var("KRABKA_PROMETHEUS_IMAGE_TAG").ok(),
        "settings":{"oracle":{"enable_type_and_unit_labels":true},"candidate":{"enable_type_and_unit_labels":true}},
        "fixture":{"timestamps_ms":[0,15000,30000,45000],"GET":[0,30,75,120],"POST":[0,3,5,8]},"cases":[]});
    let mut failures = Vec::new();
    for case in CASES {
        oracle.proxy.take()?;
        candidate.proxy.take()?;
        let expected = ledger(case);
        let mut row = json!({"id":case.id,"expression":case.expression,"independent_expected":expected,"status":"failed"});
        let result=async {
            let mut inputs=Vec::new();let mut responses=Vec::new();
            for backend in [&oracle,&candidate] {
                let input=dashboard_request(case,backend.uid);
                let response=client.post(format!("{grafana}/api/ds/query")).json(&input).send().await?;
                responses.push(json!({"status":response.status().as_u16(),"body":response.json::<Value>().await?}));
                inputs.push(input);
            }
            row["dashboard_requests"]=json!({"oracle":inputs[0],"candidate":inputs[1]});
            row["grafana_responses"]=json!({"oracle":responses[0],"candidate":responses[1]});
            let oracle_requests=oracle.proxy.take()?;let candidate_requests=candidate.proxy.take()?;
            row["generated_requests"]=json!({"oracle":oracle_requests,"candidate":candidate_requests});
            if oracle_requests.len()!=1 || oracle_requests!=candidate_requests { return Err("Grafana generated different backend requests".into()); }
            let oracle_response=replay(client,oracle.base,&oracle_requests[0]).await?;
            let candidate_response=replay(client,candidate.base,&oracle_requests[0]).await?;
            row["oracle"]=oracle_response.clone();row["candidate"]=candidate_response.clone();
            if !matches_ledger(&expected,&canonical_response(case,&oracle_response)?)
                || !matches_ledger(&expected,&canonical_response(case,&candidate_response)?)
                || canonical_frames(&responses[0],&expected)? != canonical_frames(&responses[1],&expected)? {
                return Err("Prometheus client replay differs from independent ledger or frame schema".into());
            }
            Ok::<_,Box<dyn std::error::Error+Send+Sync>>(())
        }.await;
        if let Err(error) = result {
            row["error"] = json!(error.to_string());
            failures.push(error.to_string());
        } else {
            row["status"] = json!("matched");
        }
        report["cases"]
            .as_array_mut()
            .ok_or("report cases missing")?
            .push(row);
    }
    report["status"] = json!(if failures.is_empty() {
        "passed"
    } else {
        "failed"
    });
    if let Some(directory) = std::env::var_os("TEST_UNDECLARED_OUTPUTS_DIR") {
        std::fs::write(
            std::path::PathBuf::from(directory).join("grafana-prometheus-client-replay.json"),
            serde_json::to_vec_pretty(&report)?,
        )?;
    }
    if !failures.is_empty() {
        return Err(format!("Prometheus Grafana replay failures: {failures:?}").into());
    }
    Ok(())
}

#[test]
fn independent_replay_ledger_rejects_wrong_labels_values_times_and_order() -> TestResult {
    let case = &CASES[3];
    let expected = ledger(case);
    let response = json!({"status":"success","data":{"resultType":"matrix","result":[{
        "metric":selector_labels(),"values":[[0,"0"],[15,"30"],[30,"75"],[45,"120"]]}]}});
    assert!(matches_ledger(
        &expected,
        &canonical_response(case, &response)?
    ));
    for field in ["labels", "samples"] {
        let mut wrong = expected.clone();
        wrong[field] = json!([]);
        assert!(!matches_ledger(&expected, &wrong));
    }
    for index in 0..2 {
        let mut wrong = expected.clone();
        wrong["samples"][1][index] = json!(1);
        assert!(!matches_ledger(&expected, &wrong));
    }
    let mut wrong = expected.clone();
    wrong["samples"]
        .as_array_mut()
        .ok_or("samples missing")?
        .reverse();
    assert!(!matches_ledger(&expected, &wrong));
    let mut annotated = response;
    annotated["warnings"] = json!(["unexpected warning"]);
    assert!(canonical_response(case, &annotated).is_err());
    Ok(())
}

#[test]
fn frames_retain_metric_names_and_exact_timestamp_value_associations() -> TestResult {
    let expected = ledger(&CASES[0]);
    let response = json!({"status":200,"body":{"results":{"A":{"frames":[{
        "schema":{"fields":[{"name":"Time","type":"time"},
            {"name":"http_requests_total","type":"number","labels":selector_labels()}]},
        "data":{"values":[[45000],[120]]}
    }]}}}});
    canonical_frames(&response, &expected)?;
    for column in 0..2 {
        let mut wrong = response.clone();
        wrong["body"]["results"]["A"]["frames"][0]["data"]["values"][column][0] = json!(1);
        assert!(canonical_frames(&wrong, &expected).is_err());
    }
    let mut unnamed = response;
    unnamed["body"]["results"]["A"]["frames"][0]["schema"]["fields"][1]["labels"]
        .as_object_mut()
        .ok_or("labels missing")?
        .remove("__name__");
    assert!(canonical_frames(&unnamed, &expected).is_err());
    assert!(ledger(&CASES[5])["samples"] == json!([[30000, 2.5], [45000, 3.0]]));
    Ok(())
}
